<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import {create} from '../api/datasets';import {useAsync} from '../hooks/useAsync';import {number} from '../utils/format';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const selected=ref(''),name=ref(''),source=ref('alternatives.json'),columns=ref('[{"code":"cost","label":"费用","unit":"万元"},{"code":"hours","label":"时长","unit":"小时"},{"code":"capacity","label":"舱位","unit":"TEU"}]'),text=ref('');const ds=computed(()=>props.data.datasets.find(d=>d.id===selected.value)||props.data.datasets[0]);const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await create({name:name.value,source:source.value,columns:JSON.parse(columns.value),alternatives:JSON.parse(text.value)});name.value='';text.value='';await props.refresh()})};</script><template><PageHeading code="02 / ALTERNATIVE SEGMENTS" title="方案可比较，先要指标同口径。" description="每个方案保留同一组3—6项有限数值指标。真实航道、坐标与导航指令不在本项目中。"/><section class="paper"><div class="section-heading"><h2>模拟备选航段</h2><select aria-label="选择方案集" :value="ds?.id" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></div><template v-if="ds"><div class="data-caption"><b>{{ds.alternatives.length}}个方案</b><span>{{ds.columns.length}}项指标</span><span>{{ds.source}}</span></div><div class="table-scroll"><table><thead><tr><th>方案</th><th v-for="c in ds.columns" :key="c.code">{{c.label}}<small>{{c.unit}}</small></th></tr></thead><tbody><tr v-for="a in ds.alternatives" :key="a.alternative_id"><td><b>{{a.name}}</b><small>{{a.alternative_id}}</small></td><td v-for="c in ds.columns" :key="c.code">{{number(a.values[c.code],2)}}</td></tr></tbody></table></div></template><Notice v-else>请导入至少两个方案和3—6项指标，再明确成本或收益方向。</Notice></section><section class="paper" v-if="canWrite"><h2>导入模拟方案</h2><form class="grid-form" @submit.prevent="submit"><label>方案集名称<input required minlength="2" v-model="name"/></label><label>来源文件名<input v-model="source"/></label><label class="wide">指标定义JSON<textarea rows="3" required v-model="columns"/></label><label class="wide">方案JSON数组<textarea rows="4" required v-model="text" placeholder='[{"alternative_id":"YZ-X1","name":"模拟方案X1","values":{"cost":20,"hours":24,"capacity":150}}, …]'/></label><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">核查并导入</button></form></section></template>
